/// <summary>
/// CB233_TOReceiptDetails
/// CB256_PurchaseOrderReceiptDetails
/// Service class to register inventory transactions.
/// </summary>
public class METInventTransRegisterService
{
    InventTrans    inventTrans;
    InventTransId  inventTransId;
    InventQty      qtyReceiveNow;
    PdsCWInventQty cwQtyReceiveNow;

}

Method.Source:
    /// <summary>
    /// Gets and sets inventTransId.
    /// </summary>
    /// <param name = "_inventTransId">InventTransId</param>
    /// <returns>InventTransId</returns>
    public InventTransId parmInventTransId(InventTransId _inventTransId = inventTransId)
    {
        inventTransId = _inventTransId;

        return inventTransId;
    }

    /// <summary>
    /// Gets and sets inventTransId.
    /// </summary>
    /// <param name = "_qtyReceiveNow">Qty received</param>
    /// <returns>Qty received</returns>
    public InventQty parmInventQtyReceiveNow(InventQty _qtyReceiveNow = qtyReceiveNow)
    {
        qtyReceiveNow = _qtyReceiveNow;

        return qtyReceiveNow;
    }

    /// <summary>
    /// Gets and sets CW Qty received.
    /// </summary>
    /// <param name = "_cwQtyReceiveNow">CW Qty received</param>
    /// <returns>CW Qty received</returns>
    public PdsCWInventQty parmCWInventQtyReceiveNow(PdsCWInventQty _cwQtyReceiveNow = cwQtyReceiveNow)
    {
        cwQtyReceiveNow = _cwQtyReceiveNow;

        return cwQtyReceiveNow;
    }

    /// <summary>
    /// Creates and initializes object of the service class.
    /// </summary>
    /// <param name = "_inventTransId">Inventory transaction id</param>
    /// <param name = "_qtyReceiveNow">Quantity</param>
    /// <param name = "_cwQtyReceiveNow">Catch weight quantity</param>
    /// <returns>Object of the service class</returns>
    public static METInventTransRegisterService contruct(InventTransId  _inventTransId,
                                                         InventQty      _qtyReceiveNow,
                                                         PdsCWInventQty _cwQtyReceiveNow)
    {
        METInventTransRegisterService registerService = new METInventTransRegisterService();
        
        registerService.parmInventTransId(_inventTransId);
        registerService.parmInventQtyReceiveNow(_qtyReceiveNow);
        registerService.parmCWInventQtyReceiveNow(_cwQtyReceiveNow);

        return registerService;
    }

    /// <summary>
    /// Runs the registeration process.
    /// </summary>
    public void register()
    {
        InventTransOrigin       inventTransOrigin;

        select firstonly inventTrans
            where inventTrans.StatusReceipt == StatusReceipt::Ordered
        exists join inventTransOrigin
            where inventTransOrigin.RecId == inventTrans.InventTransOrigin
            &&    inventTransOrigin.InventTransId == inventTransId;

        if (inventTrans)
        {
            this.registerInternal();
        }

    }

    /// <summary>
    /// Runs the registeration process.
    /// </summary>
    private void registerInternal()
    {
        InventTransWMS_register inventTransWMS_Register;
        TmpInventTransWMS       tmpInventTransWMS;

        delete_from tmpInventTransWMS;
            
        inventTransWMS_Register = inventTransWMS_register::newStandard(tmpInventTransWMS);
        inventTransWMS_Register.createFromInventTrans(inventTrans, inventTrans.inventDim());

        select tmpInventTransWMS;

        tmpInventTransWMS.initInventQty(qtyReceiveNow, inventTrans.StatusReceipt, inventTrans.StatusIssue);
        tmpInventTransWMS.initPdsCWQty(cwQtyReceiveNow, inventTrans.StatusReceipt, inventTrans.StatusIssue);
        inventTransWMS_Register.writeTmpInventTransWMS(tmpInventTransWMS, inventTrans, inventTrans.inventDim());
        
        inventTransWMS_Register.updateInvent(inventTrans);
    }
